1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { logActivity } from "@/lib/activity-log";
5	
6	export type TicketCartItemInput = {
7	  ticketCategoryId: string;
8	  qty: number;
9	};
10	
11	export type CheckoutTicketResult =
12	  | { success: true; invoiceNumber: string; transactionId: string }
13	  | { success: false; error: string };
14	
15	type CheckoutTicketRpcRow = { transaction_id: string; invoice_number: string };
16	
17	export async function checkoutTicket(
18	  businessId: string,
19	  cashierId: string,
20	  items: TicketCartItemInput[],
21	  paymentMethod: string,
22	  received: number | null,
23	  memberId: string | null = null,
24	): Promise<CheckoutTicketResult> {
25	  if (items.length === 0) {
26	    return { success: false, error: "Keranjang masih kosong." };
27	  }
28	
29	  const supabase = await createClient();
30	  const { data, error } = await supabase
31	    .rpc("checkout_ticket_transaction", {
32	      p_business_id: businessId,
33	      p_cashier_id: cashierId,
34	      p_items: items.map((i) => ({
35	        ticket_category_id: i.ticketCategoryId,
36	        qty: i.qty,
37	      })),
38	      p_payment_method: paymentMethod,
39	      p_received: received,
40	      p_member_id: memberId,
41	    })
42	    .single();
43	
44	  if (error || !data) {
45	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
46	  }
47	
48	  const result = data as CheckoutTicketRpcRow;
49	  const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
50	  await logActivity(
51	    supabase,
52	    businessId,
53	    "transaksi",
54	    "sukses",
55	    `Tiket ${result.invoice_number}`,
56	    `${itemCount} tiket · ${paymentMethod}`,
57	  );
58	
59	  return {
60	    success: true,
61	    invoiceNumber: result.invoice_number,
62	    transactionId: result.transaction_id,
63	  };
64	}
65	
66	export type MemberLookupResult =
67	  | { success: true; member: { id: string; name: string; memberCode: string; validUntil: string } }
68	  | { success: false; error: string };
69	
70	export async function lookupMemberByCode(
71	  businessId: string,
72	  code: string,
73	): Promise<MemberLookupResult> {
74	  const trimmed = code.trim();
75	  if (!trimmed) {
76	    return { success: false, error: "Kode member wajib diisi." };
77	  }
78	
79	  const supabase = await createClient();
80	  const { data, error } = await supabase
81	    .from("members")
82	    .select("id, name, member_code, valid_from, valid_until")
83	    .eq("business_id", businessId)
84	    .eq("member_code", trimmed)
85	    .is("deleted_at", null)
86	    .maybeSingle();
87	
88	  if (error || !data) {
89	    return { success: false, error: "Member tidak ditemukan." };
90	  }
91	
92	  const today = new Date().toISOString().slice(0, 10);
93	  if (today < data.valid_from || today > data.valid_until) {
94	    return { success: false, error: "Membership tidak aktif (kadaluarsa atau belum berlaku)." };
95	  }
96	
97	  return {
98	    success: true,
99	    member: {
100	      id: data.id,
101	      name: data.name,
102	      memberCode: data.member_code,
103	      validUntil: data.valid_until,
104	    },
105	  };
106	}
107	
108	export type VoidTicketResult = { success: true } | { success: false; error: string };
109	
110	export async function voidTicketTransaction(
111	  businessId: string,
112	  transactionId: string,
113	  managerPin: string,
114	  reason: string,
115	): Promise<VoidTicketResult> {
116	  const supabase = await createClient();
117	  const { data, error } = await supabase
118	    .rpc("void_ticket_transaction", {
119	      p_business_id: businessId,
120	      p_transaction_id: transactionId,
121	      p_manager_pin: managerPin,
122	      p_reason: reason || null,
123	    })
124	    .single();
125	
126	  if (error || !data) {
127	    return { success: false, error: error?.message ?? "Gagal membatalkan transaksi." };
128	  }
129	
130	  const row = data as { voided_by_name: string };
131	  await logActivity(
132	    supabase,
133	    businessId,
134	    "transaksi",
135	    "warning",
136	    "Transaksi tiket dibatalkan",
137	    `Oleh ${row.voided_by_name}${reason ? ` · ${reason}` : ""}`,
138	  );
139	
140	  return { success: true };
141	}
