1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { closeShift, type CloseShiftSummary } from "./actions";
6	import { checkoutTicket, lookupMemberByCode, type TicketCartItemInput } from "./ticket-actions";
7	import SwitchCashierButton from "./switch-cashier-button";
8	
9	type TicketCategory = {
10	  id: string;
11	  name: string;
12	  priceWeekday: number;
13	  priceHoliday: number;
14	  memberPrice: number;
15	};
16	
17	type Member = { id: string; name: string; memberCode: string; validUntil: string };
18	
19	const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
20	
21	function formatRupiah(value: number) {
22	  return `Rp${value.toLocaleString("id-ID")}`;
23	}
24	
25	export default function TicketPosScreen({
26	  businessId,
27	  businessName,
28	  cashierId,
29	  cashierName,
30	  shiftId,
31	  categories,
32	  taxRate,
33	  serviceRate,
34	  isHoliday,
35	  customPaymentMethods,
36	}: {
37	  businessId: string;
38	  businessName: string;
39	  cashierId: string;
40	  cashierName: string;
41	  shiftId: string;
42	  categories: TicketCategory[];
43	  taxRate: number;
44	  serviceRate: number;
45	  isHoliday: boolean;
46	  customPaymentMethods: string[];
47	}) {
48	  const router = useRouter();
49	  const paymentMethods = useMemo(
50	    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
51	    [customPaymentMethods],
52	  );
53	
54	  const [qtyByCategory, setQtyByCategory] = useState<Record<string, number>>({});
55	
56	  const [memberCode, setMemberCode] = useState("");
57	  const [member, setMember] = useState<Member | null>(null);
58	  const [memberError, setMemberError] = useState<string | null>(null);
59	  const [memberBusy, setMemberBusy] = useState(false);
60	
61	  const [paying, setPaying] = useState(false);
62	  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
63	  const [received, setReceived] = useState("");
64	  const [submitting, setSubmitting] = useState(false);
65	  const [error, setError] = useState<string | null>(null);
66	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
67	
68	  const [closingShift, setClosingShift] = useState(false);
69	  const [closingCash, setClosingCash] = useState("");
70	  const [closeNotes, setCloseNotes] = useState("");
71	  const [closeError, setCloseError] = useState<string | null>(null);
72	  const [closeSubmitting, setCloseSubmitting] = useState(false);
73	  const [closedSummary, setClosedSummary] = useState<CloseShiftSummary | null>(null);
74	
75	  function unitPriceFor(category: TicketCategory) {
76	    if (member) return category.memberPrice;
77	    return isHoliday ? category.priceHoliday : category.priceWeekday;
78	  }
79	
80	  function changeQty(categoryId: string, delta: number) {
81	    setQtyByCategory((prev) => {
82	      const nextQty = Math.max(0, (prev[categoryId] ?? 0) + delta);
83	      const next = { ...prev };
84	      if (nextQty <= 0) {
85	        delete next[categoryId];
86	      } else {
87	        next[categoryId] = nextQty;
88	      }
89	      return next;
90	    });
91	  }
92	
93	  const cartLines = categories
94	    .filter((c) => (qtyByCategory[c.id] ?? 0) > 0)
95	    .map((c) => ({
96	      category: c,
97	      qty: qtyByCategory[c.id],
98	      unitPrice: unitPriceFor(c),
99	    }));
100	
101	  const subtotal = cartLines.reduce((sum, l) => sum + l.unitPrice * l.qty, 0);
102	  const serviceAmt = serviceRate > 0 ? Math.round((subtotal * serviceRate) / 100) : 0;
103	  const taxAmt = taxRate > 0 ? Math.round(((subtotal + serviceAmt) * taxRate) / 100) : 0;
104	  const total = subtotal + serviceAmt + taxAmt;
105	  const receivedAmount = Number(received) || 0;
106	  const change = paymentMethod === "Tunai" ? receivedAmount - total : 0;
107	
108	  async function handleLookupMember() {
109	    setMemberError(null);
110	    setMemberBusy(true);
111	    const result = await lookupMemberByCode(businessId, memberCode);
112	    setMemberBusy(false);
113	    if (!result.success) {
114	      setMemberError(result.error);
115	      return;
116	    }
117	    setMember(result.member);
118	  }
119	
120	  async function handleConfirmPayment() {
121	    setError(null);
122	
123	    if (paymentMethod === "Tunai" && receivedAmount < total) {
124	      setError("Uang diterima kurang dari total.");
125	      return;
126	    }
127	
128	    const items: TicketCartItemInput[] = cartLines.map((l) => ({
129	      ticketCategoryId: l.category.id,
130	      qty: l.qty,
131	    }));
132	
133	    setSubmitting(true);
134	    const result = await checkoutTicket(
135	      businessId,
136	      cashierId,
137	      items,
138	      paymentMethod,
139	      paymentMethod === "Tunai" ? receivedAmount : total,
140	      member?.id ?? null,
141	    );
142	    setSubmitting(false);
143	
144	    if (!result.success) {
145	      setError(result.error);
146	      return;
147	    }
148	
149	    setSuccessInvoice(result.invoiceNumber);
150	  }
151	
152	  async function handleConfirmCloseShift() {
153	    setCloseError(null);
154	
155	    const amount = Number(closingCash);
156	    if (!closingCash || Number.isNaN(amount) || amount < 0) {
157	      setCloseError("Jumlah kas harus angka dan tidak boleh negatif.");
158	      return;
159	    }
160	
161	    setCloseSubmitting(true);
162	    const result = await closeShift(businessId, shiftId, amount, closeNotes);
163	    setCloseSubmitting(false);
164	
165	    if (!result.success) {
166	      setCloseError(result.error);
167	      return;
168	    }
169	
170	    setClosedSummary(result.summary);
171	  }
172	
173	  function resetForNextTransaction() {
174	    setSuccessInvoice(null);
175	    setQtyByCategory({});
176	    setMember(null);
177	    setMemberCode("");
178	    setPaying(false);
179	    setReceived("");
180	    router.refresh();
181	  }
182	
183	  if (successInvoice) {
184	    return (
185	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
186	        <div className="w-full max-w-sm rounded-2xl border border-zinc-200 bg-white p-6 text-center">
187	          <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-brand-50 text-2xl">
188	            🎟️
189	          </div>
190	          <h1 className="text-lg font-bold text-zinc-900">Tiket berhasil terbit</h1>
191	          <p className="mt-1 text-sm text-zinc-500">No. Tiket: {successInvoice}</p>
192	          <button
193	            onClick={resetForNextTransaction}
194	            className="mt-6 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
195	          >
196	            Transaksi Baru
197	          </button>
198	        </div>
199	      </div>
200	    );
201	  }
202	
203	  if (closedSummary) {
204	    const diff = closedSummary.difference;
205	    return (
206	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
207	        <div className="w-full max-w-sm rounded-2xl border border-zinc-200 bg-white p-6">
208	          <h1 className="text-center text-lg font-bold text-zinc-900">Shift Ditutup</h1>
209	          <div className="mt-4 space-y-2 text-sm">
210	            <div className="flex justify-between text-zinc-600">
211	              <span>Total Penjualan</span>
212	              <span className="font-medium text-zinc-900">
213	                {formatRupiah(closedSummary.total_sales)}
214	              </span>
215	            </div>
216	            <div className="flex justify-between text-zinc-600">
217	              <span>Penjualan Tunai</span>
218	              <span className="font-medium text-zinc-900">
219	                {formatRupiah(closedSummary.cash_sales)}
220	              </span>
221	            </div>
222	            <div className="flex justify-between text-zinc-600">
223	              <span>Penjualan Non-Tunai</span>
224	              <span className="font-medium text-zinc-900">
225	                {formatRupiah(closedSummary.non_cash_sales)}
226	              </span>
227	            </div>
228	            <div className="flex justify-between text-zinc-600">
229	              <span>Jumlah Transaksi</span>
230	              <span className="font-medium text-zinc-900">{closedSummary.tx_count}</span>
231	            </div>
232	            <div className="flex justify-between border-t border-zinc-100 pt-2 text-zinc-600">
233	              <span>Kas Diharapkan</span>
234	              <span className="font-medium text-zinc-900">
235	                {formatRupiah(closedSummary.expected_cash)}
236	              </span>
237	            </div>
238	            <div className="flex justify-between font-semibold">
239	              <span className={diff === 0 ? "text-zinc-900" : diff > 0 ? "text-brand-700" : "text-red-600"}>
240	                Selisih
241	              </span>
242	              <span className={diff === 0 ? "text-zinc-900" : diff > 0 ? "text-brand-700" : "text-red-600"}>
243	                {diff === 0 ? "Pas" : `${diff > 0 ? "+" : ""}${formatRupiah(diff)}`}
244	              </span>
245	            </div>
246	          </div>
247	          <button
248	            onClick={() => router.refresh()}
249	            className="mt-6 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
250	          >
251	            Selesai
252	          </button>
253	        </div>
254	      </div>
255	    );
256	  }
257	
258	  if (closingShift) {
259	    return (
260	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
261	        <div className="w-full max-w-sm rounded-2xl border border-zinc-200 bg-white p-6">
262	          <h1 className="text-lg font-bold text-zinc-900">Tutup Shift</h1>
263	          <p className="mt-1 text-sm text-zinc-500">
264	            Hitung uang tunai di laci, lalu masukkan jumlahnya.
265	          </p>
266	
267	          <div className="mt-4 space-y-4">
268	            <div>
269	              <label htmlFor="closingCash" className="mb-1 block text-xs font-medium text-zinc-600">
270	                Kas di Laci Sekarang (Rp)
271	              </label>
272	              <input
273	                id="closingCash"
274	                type="number"
275	                min="0"
276	                value={closingCash}
277	                onChange={(e) => setClosingCash(e.target.value)}
278	                className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
279	                placeholder="mis. 750000"
280	              />
281	            </div>
282	            <div>
283	              <label htmlFor="closeNotes" className="mb-1 block text-xs font-medium text-zinc-600">
284	                Catatan (opsional)
285	              </label>
286	              <input
287	                id="closeNotes"
288	                type="text"
289	                value={closeNotes}
290	                onChange={(e) => setCloseNotes(e.target.value)}
291	                className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
292	              />
293	            </div>
294	
295	            {closeError && (
296	              <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{closeError}</p>
297	            )}
298	
299	            <button
300	              onClick={handleConfirmCloseShift}
301	              disabled={closeSubmitting}
302	              className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
303	            >
304	              {closeSubmitting ? "Memproses…" : "Tutup Shift"}
305	            </button>
306	            <button
307	              onClick={() => {
308	                setClosingShift(false);
309	                setCloseError(null);
310	              }}
311	              className="w-full py-1 text-center text-xs font-medium text-zinc-400 hover:text-zinc-600"
312	            >
313	              Batal
314	            </button>
315	          </div>
316	        </div>
317	      </div>
318	    );
319	  }
320	
321	  return (
322	    <div className="flex flex-1 flex-col md:flex-row">
323	      {/* Kategori tiket */}
324	      <div className="flex-1 overflow-y-auto p-4">
325	        <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
326	          <div>
327	            <h1 className="text-lg font-bold text-zinc-900">{businessName}</h1>
328	            <p className="text-xs text-zinc-500">Kasir: {cashierName}</p>
329	          </div>
330	          <span
331	            className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${
332	              isHoliday ? "bg-amber-50 text-amber-700" : "bg-zinc-100 text-zinc-600"
333	            }`}
334	          >
335	            {isHoliday ? "🌴 Hari Libur" : "📅 Hari Kerja"}
336	          </span>
337	        </div>
338	
339	        <div className="mb-4 rounded-xl border border-zinc-200 bg-white p-3.5">
340	          <p className="mb-2 text-xs font-medium text-zinc-600">Member (opsional)</p>
341	          {member ? (
342	            <div className="flex items-center justify-between rounded-lg bg-brand-50 px-3 py-2">
343	              <div>
344	                <p className="text-sm font-semibold text-brand-700">{member.name}</p>
345	                <p className="text-[11px] text-brand-600">
346	                  {member.memberCode} · berlaku s/d{" "}
347	                  {new Date(member.validUntil).toLocaleDateString("id-ID")}
348	                </p>
349	              </div>
350	              <button
351	                onClick={() => {
352	                  setMember(null);
353	                  setMemberCode("");
354	                }}
355	                className="text-xs font-medium text-brand-700 hover:underline"
356	              >
357	                Lepas
358	              </button>
359	            </div>
360	          ) : (
361	            <div className="flex gap-2">
362	              <input
363	                type="text"
364	                value={memberCode}
365	                onChange={(e) => setMemberCode(e.target.value)}
366	                placeholder="Kode member"
367	                className="flex-1 rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
368	              />
369	              <button
370	                onClick={handleLookupMember}
371	                disabled={memberBusy}
372	                className="rounded-lg bg-zinc-900 px-4 text-xs font-semibold text-white hover:bg-zinc-800 disabled:opacity-60"
373	              >
374	                {memberBusy ? "Mencari…" : "Cari"}
375	              </button>
376	            </div>
377	          )}
378	          {memberError && <p className="mt-1.5 text-xs text-red-600">{memberError}</p>}
379	        </div>
380	
381	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
382	          {categories.map((c) => {
383	            const qty = qtyByCategory[c.id] ?? 0;
384	            const price = unitPriceFor(c);
385	            return (
386	              <div
387	                key={c.id}
388	                className="rounded-2xl border border-zinc-200 bg-white p-4 text-center"
389	              >
390	                <p className="text-sm font-bold text-zinc-900">{c.name}</p>
391	                <p className="mt-1 text-xs text-zinc-500">{formatRupiah(price)}</p>
392	                <div className="mt-3 flex items-center justify-center gap-3">
393	                  <button
394	                    onClick={() => changeQty(c.id, -1)}
395	                    disabled={qty <= 0}
396	                    className="flex h-8 w-8 items-center justify-center rounded-full border border-zinc-200 text-zinc-600 disabled:opacity-40"
397	                  >
398	                    −
399	                  </button>
400	                  <span className="w-6 text-sm font-semibold tabular-nums">{qty}</span>
401	                  <button
402	                    onClick={() => changeQty(c.id, 1)}
403	                    className="flex h-8 w-8 items-center justify-center rounded-full border border-zinc-200 text-zinc-600 hover:border-brand-300 hover:text-brand-700"
404	                  >
405	                    +
406	                  </button>
407	                </div>
408	              </div>
409	            );
410	          })}
411	          {categories.length === 0 && (
412	            <p className="col-span-full py-12 text-center text-xs text-zinc-400">
413	              Belum ada kategori tiket. Tambahkan lewat menu Pengaturan.
414	            </p>
415	          )}
416	        </div>
417	      </div>
418	
419	      {/* Keranjang & pembayaran */}
420	      <div className="flex w-full flex-col border-t border-zinc-200 bg-white p-4 md:w-80 md:border-l md:border-t-0">
421	        <div className="flex-1 space-y-2 overflow-y-auto">
422	          {cartLines.length === 0 ? (
423	            <p className="py-12 text-center text-xs text-zinc-400">Belum ada tiket dipilih</p>
424	          ) : (
425	            cartLines.map((l) => (
426	              <div key={l.category.id} className="flex items-center justify-between text-sm">
427	                <span className="text-zinc-700">
428	                  {l.qty}x {l.category.name}
429	                </span>
430	                <span className="tabular-nums text-zinc-900">
431	                  {formatRupiah(l.unitPrice * l.qty)}
432	                </span>
433	              </div>
434	            ))
435	          )}
436	        </div>
437	
438	        <div className="mt-3 space-y-1 border-t border-zinc-100 pt-3">
439	          <div className="flex items-center justify-between text-xs text-zinc-500">
440	            <span>Subtotal</span>
441	            <span className="tabular-nums">{formatRupiah(subtotal)}</span>
442	          </div>
443	          {serviceAmt > 0 && (
444	            <div className="flex items-center justify-between text-xs text-zinc-500">
445	              <span>Layanan ({serviceRate}%)</span>
446	              <span className="tabular-nums">{formatRupiah(serviceAmt)}</span>
447	            </div>
448	          )}
449	          {taxAmt > 0 && (
450	            <div className="flex items-center justify-between text-xs text-zinc-500">
