1	export type Period = "today" | "week" | "month" | "all" | "custom";
2	
3	export const PERIOD_LABELS: Record<Period, string> = {
4	  today: "Hari Ini",
5	  week: "7 Hari",
6	  month: "Bulan Ini",
7	  all: "Semua",
8	  custom: "📅 Kustom",
9	};
10	
11	export const PERIOD_DESCRIPTIONS: Record<Period, string> = {
12	  today: "Hari ini",
13	  week: "7 hari terakhir",
14	  month: "Bulan ini",
15	  all: "Semua waktu",
16	  custom: "Periode kustom",
17	};
18	
19	// Seluruh UI berbahasa Indonesia; batas hari & jam laporan dihitung di zona WIB,
20	// bukan zona server (yang bisa saja UTC saat production).
21	export const REPORT_TIMEZONE = "Asia/Jakarta";
22	
23	export function parsePeriod(value: string | undefined): Period {
24	  return (["today", "week", "month", "all", "custom"] as const).includes(value as Period)
25	    ? (value as Period)
26	    : "today";
27	}
28	
29	function todayStr() {
30	  return new Date().toLocaleDateString("en-CA", { timeZone: REPORT_TIMEZONE });
31	}
32	
33	function addDaysStr(dateStr: string, days: number) {
34	  const d = new Date(`${dateStr}T00:00:00Z`);
35	  d.setUTCDate(d.getUTCDate() + days);
36	  return d.toISOString().slice(0, 10);
37	}
38	
39	/** Ubah tanggal lokal WIB (YYYY-MM-DD) jadi timestamp UTC awal hari itu. */
40	function wibStartOfDay(dateStr: string) {
41	  return `${dateStr}T00:00:00+07:00`;
42	}
43	
44	export type DateRange = { fromIso: string | null; toIsoExclusive: string | null };
45	
46	/**
47	 * Rentang timestamptz [fromIso, toIsoExclusive) untuk filter kolom
48	 * `transactions.date` sesuai periode laporan.
49	 */
50	export function getPeriodRange(
51	  period: Period,
52	  customFrom?: string,
53	  customTo?: string,
54	): DateRange {
55	  const today = todayStr();
56	  if (period === "today") {
57	    return { fromIso: wibStartOfDay(today), toIsoExclusive: null };
58	  }
59	  if (period === "week") {
60	    return { fromIso: wibStartOfDay(addDaysStr(today, -6)), toIsoExclusive: null };
61	  }
62	  if (period === "month") {
63	    return { fromIso: wibStartOfDay(`${today.slice(0, 7)}-01`), toIsoExclusive: null };
64	  }
65	  if (period === "custom") {
66	    const isDate = (s: string | undefined): s is string => !!s && /^\d{4}-\d{2}-\d{2}$/.test(s);
67	    return {
68	      fromIso: isDate(customFrom) ? wibStartOfDay(customFrom) : null,
69	      toIsoExclusive: isDate(customTo) ? wibStartOfDay(addDaysStr(customTo, 1)) : null,
70	    };
71	  }
72	  return { fromIso: null, toIsoExclusive: null };
73	}
