7	type ParsedMemberFields =
8	  | { error: string }
9	  | {
10	      error: null;
11	      name: string;
12	      phone: string;
13	      memberCode: string;
14	      validFrom: string;
15	      validUntil: string;
16	      note: string;
17	    };
18	
19	function parseMemberFields(formData: FormData): ParsedMemberFields {
20	  const name = (formData.get("name") as string)?.trim();
21	  const phone = (formData.get("phone") as string)?.trim();
22	  const memberCode = (formData.get("memberCode") as string)?.trim();
23	  const validFrom = formData.get("validFrom") as string;
24	  const validUntil = formData.get("validUntil") as string;
25	  const note = (formData.get("note") as string)?.trim();
26	
27	  if (!name) return { error: "Nama member wajib diisi." };
28	  if (!memberCode) return { error: "Kode member wajib diisi." };
29	  if (!validFrom || !/^\d{4}-\d{2}-\d{2}$/.test(validFrom)) {
30	    return { error: "Tanggal mulai berlaku wajib diisi." };
31	  }
32	  if (!validUntil || !/^\d{4}-\d{2}-\d{2}$/.test(validUntil)) {
33	    return { error: "Tanggal berakhir wajib diisi." };
34	  }
35	  if (validUntil < validFrom) {
36	    return { error: "Tanggal berakhir tidak boleh sebelum tanggal mulai." };
37	  }
38	
39	  return { error: null, name, phone, memberCode, validFrom, validUntil, note };
40	}
41	
42	export type AddMemberState = { error: string | null };
43	
44	export async function addMember(
45	  businessId: string,
46	  _prevState: AddMemberState,
47	  formData: FormData,
48	): Promise<AddMemberState> {
49	  const parsed = parseMemberFields(formData);
50	  if (parsed.error !== null) return { error: parsed.error };
51	
52	  const supabase = await createClient();
53	  const { error } = await supabase.from("members").insert({
54	    business_id: businessId,
55	    name: parsed.name,
56	    phone: parsed.phone || null,
57	    member_code: parsed.memberCode,
58	    valid_from: parsed.validFrom,
59	    valid_until: parsed.validUntil,
60	    note: parsed.note || null,
61	  });
62	
63	  if (error) {
64	    if (error.code === "23505") {
65	      return { error: "Kode member sudah dipakai member lain." };
66	    }
67	    return { error: error.message };
68	  }
69	
70	  await logActivity(supabase, businessId, "produk", "sukses", `Member baru: ${parsed.name}`);
71	  revalidatePath(`/business/${businessId}/members`);
72	  return { error: null };
73	}
