75	export type EditMemberState = { error: string | null };
76	
77	export async function editMember(
78	  businessId: string,
79	  memberId: string,
80	  _prevState: EditMemberState,
81	  formData: FormData,
82	): Promise<EditMemberState> {
83	  const parsed = parseMemberFields(formData);
84	  if (parsed.error !== null) return { error: parsed.error };
85	
86	  const supabase = await createClient();
87	  const { error } = await supabase
88	    .from("members")
89	    .update({
90	      name: parsed.name,
91	      phone: parsed.phone || null,
92	      member_code: parsed.memberCode,
93	      valid_from: parsed.validFrom,
94	      valid_until: parsed.validUntil,
95	      note: parsed.note || null,
96	    })
97	    .eq("id", memberId)
98	    .eq("business_id", businessId);
99	
100	  if (error) {
101	    if (error.code === "23505") {
102	      return { error: "Kode member sudah dipakai member lain." };
103	    }
104	    return { error: error.message };
105	  }
106	
107	  await logActivity(supabase, businessId, "produk", "info", `Member diubah: ${parsed.name}`);
108	  revalidatePath(`/business/${businessId}/members`);
109	  revalidatePath(`/business/${businessId}/members/${memberId}`);
110	  return { error: null };
111	}
